import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { Documento } from '../models/documento.model';
import { firstValueFrom } from 'rxjs';
import { LocalStorageService } from '../services/localStorage/local-storage.service';

@Injectable({
  providedIn: 'any'
})
export class DocumentoService extends SuperService<Documento> {
  protected override model ='documentos'
  protected override columns: (keyof Documento)[] =[
    "usuario_id",
    "nombre"
  ];

  constructor(injector: Injector){
    super(injector)
  }

  override async new(data: Partial<Documento>) {
    data.usuario_id= this.storage.getUser().id
    return (await firstValueFrom(this.api.post<Documento>(this.url(), data))).data;
  }
}
